@SupportedAnnotationTypes("Tracked")
static class KindAwareProcessor extends AbstractProcessor {
    @Override
    public SourceVersion getSupportedSourceVersion() { return SourceVersion.latestSupported(); }
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement type : annotations) {
            for (Element el : roundEnv.getElementsAnnotatedWith(type)) {
                if (el.getKind() == ElementKind.METHOD) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.NOTE, "Sledzona metoda: " + el.getSimpleName());
                } else if (el.getKind() == ElementKind.FIELD) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.NOTE, "Sledzone pole: " + el.getSimpleName());
                }
            }
        }
        return true;
    }
}

@SupportedAnnotationTypes("RequiresJustification")
static class JustificationProcessor extends AbstractProcessor {
    @Override
    public SourceVersion getSupportedSourceVersion() { return SourceVersion.latestSupported(); }
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement type : annotations) {
            for (Element el : roundEnv.getElementsAnnotatedWith(type)) {
                for (AnnotationMirror am : el.getAnnotationMirrors()) {
                    for (var entry : am.getElementValues().entrySet()) {
                        String value = entry.getValue().getValue().toString();
                        if (value.isBlank()) {
                            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Brak uzasadnienia", el);
                        }
                    }
                }
            }
        }
        return true;
    }
}
