@SupportedAnnotationTypes("GenerateToString")
static class GeneratingProcessor extends AbstractProcessor {
    @Override
    public SourceVersion getSupportedSourceVersion() { return SourceVersion.latestSupported(); }
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement type : annotations) {
            for (Element el : roundEnv.getElementsAnnotatedWith(type)) {
                try {
                    String name = el.getSimpleName() + "Describer";
                    JavaFileObject file = processingEnv.getFiler().createSourceFile(name);
                    try (var writer = file.openWriter()) {
                        writer.write("public class " + name + " { public static String describe() { return \"opis\"; } }");
                    }
                } catch (Exception e) { }
            }
        }
        return true;
    }
}
