// Wariant z refleksja (wolniejszy w runtime - kazde wywolanie odczytuje adnotacje/pola przez Reflection API):
class Employee { String name; }
class EmployeeDto { String name; }

static EmployeeDto mapReflective(Employee e) throws Exception {
    EmployeeDto dto = new EmployeeDto();
    Field src = Employee.class.getDeclaredField("name");
    Field dst = EmployeeDto.class.getDeclaredField("name");
    src.setAccessible(true); dst.setAccessible(true);
    dst.set(dto, src.get(e));
    return dto;
}

