@SupportedAnnotationTypes("Range")
static class RangeValidationProcessor extends AbstractProcessor {
    @Override
    public SourceVersion getSupportedSourceVersion() { return SourceVersion.latestSupported(); }
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement type : annotations) {
            for (Element el : roundEnv.getElementsAnnotatedWith(type)) {
                for (AnnotationMirror am : el.getAnnotationMirrors()) {
                    Integer min = null, max = null;
                    for (var entry : am.getElementValues().entrySet()) {
                        String key = entry.getKey().getSimpleName().toString();
                        int val = (int) entry.getValue().getValue();
                        if (key.equals("min")) min = val;
                        if (key.equals("max")) max = val;
                    }
                    if (min != null && max != null && min > max) {
                        processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "min > max w @Range", el);
                    }
                }
            }
        }
        return true;
    }
}

